"""Base Strategy Abstraction and Data Contracts for NEPSE Trading Signal Engine."""

from __future__ import annotations

import datetime
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Any

from apps.securities.models import Security
from apps.technical_analysis.indicators import FullIndicatorSet
from apps.technical_analysis.indicators.types import Candle


@dataclass(frozen=True)
class StrategySignalCandidate:
    """Represents a validated trading signal proposal generated by a strategy."""

    security: Security
    strategy_type: str  # "short_term" or "swing"
    setup_type: str  # "breakout", "pullback", "support_rebound", "trend_continuation", etc.
    signal_date: datetime.date
    suggested_entry: Decimal
    entry_zone_low: Decimal
    entry_zone_high: Decimal
    stop_loss: Decimal
    target_1: Decimal
    target_2: Decimal | None
    risk_per_share: Decimal
    risk_reward_ratio: Decimal
    composite_score: Decimal
    max_holding_period: int
    rationale: str
    metadata: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class ExitEvaluationResult:
    """Result of checking an active position against strategy exit rules."""

    should_exit: bool
    exit_reason: str | None = None
    exit_type: str | None = None  # "target_1_hit", "target_2_hit", "stopped_out", "expired", "closed"
    exit_price: Decimal | None = None
    is_stop_loss: bool = False
    is_target_1: bool = False
    is_target_2: bool = False
    is_time_exit: bool = False
    updated_trailing_stop: Decimal | None = None
    notes: str = ""


class BaseStrategy(ABC):
    """Abstract Base Class for NEPSE quantitative trading strategies."""

    name: str = "Base Strategy"
    strategy_type: str = "base"
    min_holding_period: int = 1
    max_holding_period: int = 10

    @abstractmethod
    def evaluate_security(
        self,
        security: Security,
        candles: list[Candle],
        indicators: FullIndicatorSet,
        *,
        market_context: dict[str, Any] | None = None,
        sector_context: dict[str, Any] | None = None,
    ) -> StrategySignalCandidate | None:
        """Analyze a security's historical candles and indicators to generate a signal candidate.

        Args:
            security: The Security instance.
            candles: Chronologically sorted candles up to the signal date.
            indicators: Calculated FullIndicatorSet for the latest candle.
            market_context: Optional market-wide breadth and trend metrics.
            sector_context: Optional sector relative strength and rotation metrics.

        Returns:
            StrategySignalCandidate if setup satisfies all criteria, else None.
        """
        raise NotImplementedError

    @abstractmethod
    def check_exit_conditions(
        self,
        current_candle: Candle,
        entry_price: Decimal,
        stop_loss: Decimal,
        target_1: Decimal,
        target_2: Decimal | None,
        trailing_stop: Decimal | None,
        days_in_trade: int,
        indicators: FullIndicatorSet | None = None,
    ) -> ExitEvaluationResult:
        """Evaluate exit conditions for an active trade given the current session's candle.

        Args:
            current_candle: Today's OHLCV candle.
            entry_price: Original fill price.
            stop_loss: Active stop-loss level.
            target_1: First profit target.
            target_2: Second profit target.
            trailing_stop: Current trailing stop level (if any).
            days_in_trade: Sessions elapsed since fill.
            indicators: Current indicator snapshot (optional).

        Returns:
            ExitEvaluationResult indicating whether to exit or modify trailing stop.
        """
        raise NotImplementedError
